# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: gather
def gather(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: render
def render(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(sift(gather(fold(raw))))

